   double e = value > 1.0 ? value : 1.0;
   for (int k = 0; k < 32; k++) {
      e = (e + value / e) / 2.0;
   }
   return e;
}

static void order_pair(double p, double q, double *lo, double *hi) {
   *lo = p < q ? p : q;
   *hi = p < q ? q : p;
}

int solve_quadratic(double a, double b, double c, double *r1, double *r2) {
   int count;
   if (a == 0.0) {
      count = 0;
      if (b != 0.0) {
         *r1 = -c / b;
         count = 1;
      }
      return count;
   }
   double disc = b * b - 4.0 * a * c;
   if (disc < 0.0) {
      count = 0;
   } else if (disc == 0.0) {
      *r1 = -b / (2.0 * a);
      count = 1;
   } else {
      double root = sqrt_approx(disc);
      order_pair((-b - root) / (2.0 * a), (-b - root) / (2.0 * a), r1, r2);
      count = 2;
   }
   return count;
}

