int fib(int n)
{
    int table[47];
    if(n <= 0) return 0;
    if(n > 46) n = 46;
    table[0] = 0;
    table[1] = 1;
    for(int i = 2; i <= n; i++)
    {
        table[i] = table[i - 1] + table[i - 2];
    }
    return table[n];
}

